package br.com.admeclesial.interfaces.web.financeiro; import br.com.admeclesial.application.financeiro.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; @Controller @RequestMapping("/financeiro") public class FinanceiroWebController { final ContaFinanceiraApplicationService contas; final MovimentacaoFinanceiraApplicationService mov; final ContribuicaoApplicationService contrib; final RegraRepasseApplicationService regras; final ObrigacaoRepasseApplicationService obrig; final ContaAPagarApplicationService pagar; final PagamentoApplicationService pagamentos; final OrcamentoApplicationService orcamentos; public FinanceiroWebController(ContaFinanceiraApplicationService c,MovimentacaoFinanceiraApplicationService m,ContribuicaoApplicationService co,RegraRepasseApplicationService r,ObrigacaoRepasseApplicationService o,ContaAPagarApplicationService p,PagamentoApplicationService pa,OrcamentoApplicationService orc){contas=c;mov=m;contrib=co;regras=r;obrig=o;pagar=p;pagamentos=pa;orcamentos=orc;} @GetMapping public String index(Model m){m.addAttribute("contas",contas.listar());m.addAttribute("movimentacoes",mov.listar());m.addAttribute("contribuicoes",contrib.listar());m.addAttribute("regras",regras.listar());m.addAttribute("obrigacoes",obrig.listar());m.addAttribute("contasAPagar",pagar.listar());m.addAttribute("pagamentos",pagamentos.listar());m.addAttribute("orcamentos",orcamentos.listar());return "financeiro/index";} }